gact(){return"\u041e\u0442\u0432\u0435\u0442: \u041d\u0430\u0439\u0434\u0438\u0442\u0435 \u043d\u0443\u0436\u043d\u043e\u0433\u043e \u0441\u0442\u0443\u0434\u0435\u043d\u0442\u0430 \u0432 \u043f\u043e\u0438\u0441\u043a\u0435 \u0438\u043b\u0438 \u0432 \u0441\u043f\u0438\u0441\u043a\u0435 \u0434\u0440\u0443\u0437\u0435\u0439, \u0441\u0434\u0435\u043b\u0430\u0439\u0442\u0435 \u0441\u0432\u0430\u0439\u043f \u0441\u043b\u0435\u0432\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u043e \u043f\u043e \u0435\u0433\u043e \u043a\u0430\u0440\u0442\u043e\u0447\u043a\u0435 \u0438 \u043d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u043f\u043e\u044f\u0432\u0438\u0432\u0448\u0443\u044e\u0441\u044f \u0438\u043a\u043e\u043d\u043a\u0443 \u043f\u0440\u043e\u0444\u0438\u043b\u044f (\u043b\u0443\u043f\u0430 \u0441 \u0447\u0435\u043b\u043e\u0432\u0435\u043a\u043e\u043c)."},
